    const originalFetch = window.fetch ? window.fetch.bind(window) : null;

    function normalizePath(input) {
        let raw = typeof input === 'string' ? input : input?.url;
        if (!raw) return '';

        raw = String(raw).split('#')[0].split('?')[0].replace(/\\/g, '/');

        if (/^https?:\/\//i.test(raw)) return raw;

        if (raw.startsWith('file:///')) {
            try {
                raw = decodeURIComponent(new URL(raw).pathname).replace(/\\/g, '/');
            } catch (error) {
                raw = raw.replace(/^file:\/\/\//i, '');
            }
        }

        raw = raw.replace(/^\/+/, '').replace(/^\.\//, '');
        while (raw.startsWith('../')) raw = raw.slice(3);

        const htmlIndex = raw.indexOf('/html/');
        if (htmlIndex >= 0) raw = raw.slice(htmlIndex + 1);

        const jsonIndex = raw.indexOf('/json/');
        if (jsonIndex >= 0) raw = raw.slice(jsonIndex + 1);

        if (raw.endsWith('/index.html')) return 'index.html';

        return raw;
    }

    function makeResponse(key, body) {
        const contentType = key.endsWith('.json') ? 'application/json' : 'text/html';
        return new Response(body, {
            status: 200,
            statusText: 'OK',
            headers: { 'Content-Type': `${contentType}; charset=utf-8` }
        });
    }

    window.__LOCAL_FILES = LOCAL_FILES;
    window.fetch = function (input, init) {
        const key = normalizePath(input);

        if (Object.prototype.hasOwnProperty.call(LOCAL_FILES, key)) {
            return Promise.resolve(makeResponse(key, LOCAL_FILES[key]));
        }

        if (originalFetch) return originalFetch(input, init);
        return Promise.reject(new Error(`No local data for ${key}`));
    };
